<script>import {onMount} from 'svelte';import {linkTreesStore} from '../states/linkTreesStore.js';import * as api from '../api/linkTreeApi.js';import {router} from '../../../router.js';import {getErrorMessage, safeUrl} from '../../../helpers/toolsHelper.js';import ChangeModal from '../modals/ChangeModal.svelte';import ChangeCoverModal from '../modals/ChangeCoverModal.svelte';import ItemModal from '../modals/ItemModal.svelte';let id=$derived(decodeURIComponent(router.path.split('/')[2]||''));let item=$derived(linkTreesStore.detail);let loadError=$state('');let notice=$state('');let editing=$state(false);let editingCover=$state(false);let itemEditor=$state(null);let addItem=$state(false);let busy=$state(false);async function load(){try{await linkTreesStore.fetchOne(id)}catch(e){loadError=getErrorMessage(e)}}onMount(load);async function saveTree(data){busy=true;try{await api.updateLinkTree(id,data);editing=false;await load();notice='Informasi Link Tree diperbarui.'}finally{busy=false}}async function saveCover(file){busy=true;try{await api.uploadCover(id,file);editingCover=false;await load();notice='Sampul berhasil diperbarui.'}finally{busy=false}}async function saveItem(data){busy=true;try{if(itemEditor)await api.updateItem(id,itemEditor.id,data);else await api.createItem(id,data);itemEditor=null;addItem=false;await load();notice='Tautan berhasil disimpan.'}finally{busy=false}}async function removeItem(link){if(!confirm(`Hapus tautan “${link.title}”?`))return;try{await api.deleteItem(id,link.id);await load();notice='Tautan dihapus.'}catch(e){notice=getErrorMessage(e)}}async function removeTree(){if(!confirm('Hapus Link Tree ini beserta pengaturannya?'))return;try{await api.deleteLinkTree(id);router.navigate('/')}catch(e){notice=getErrorMessage(e)}}</script>
<svelte:head><title>{item?.title||'Detail Link Tree'} · Delcom</title><meta name="description" content={item?.description||'Kelola koleksi tautan di Delcom Link Tree.'}/></svelte:head><div class="breadcrumb"><a href="/" onclick={(e)=>{e.preventDefault();router.navigate('/')}}>Semua Link Tree</a><span>/</span><span>Detail</span></div>{#if linkTreesStore.loading}<div class="loading-state">Memuat detail link tree…</div>{:else if loadError}<div class="empty-state"><h2>Link Tree tidak dapat dibuka</h2><p>{loadError}</p><button class="btn btn-light" onclick={()=>router.navigate('/')}>Kembali</button></div>{:else if item}<div class="detail-heading"><div><p class="eyebrow">DETAIL KOLEKSI</p><h1>{item.title}</h1><p class="muted">{item.description||'Belum ada deskripsi.'}</p></div><div class="button-row"><button class="btn btn-light" onclick={()=>editing=true}>Ubah data</button><button class="btn btn-danger" onclick={removeTree}>Hapus</button></div></div>{#if notice}<div class="notice" role="status">{notice}<button aria-label="Tutup pemberitahuan" onclick={()=>notice=''}>×</button></div>{/if}<section class="detail-cover">{#if item.cover}<img src={item.cover} alt="Sampul koleksi"/>{:else}<div class="cover-placeholder"><span>↗</span><p>Tambahkan sampul untuk koleksimu</p></div>{/if}<button class="btn btn-light cover-edit" onclick={()=>editingCover=true}>Ubah sampul</button></section><section class="list-section"><div class="section-heading"><div><h2>Daftar tautan</h2><p class="muted">{item.items?.length||0} tautan di koleksi ini.</p></div><button class="btn btn-primary" onclick={()=>addItem=true}>＋ Tambah tautan</button></div>{#if !item.items?.length}<div class="empty-state compact"><span>↗</span><h3>Belum ada tautan</h3><p>Tambahkan tautan pertama ke koleksi ini.</p></div>{:else}<div class="link-list">{#each item.items as link (link.id)}<article class="link-row"><div class="link-favicon">↗</div><div class="link-info"><h3>{link.title}</h3><a href={safeUrl(link.url)||undefined} target="_blank" rel="noopener noreferrer">{link.url}</a>{#if link.description}<p>{link.description}</p>{/if}</div><div class="button-row"><button class="btn btn-light btn-small" onclick={()=>{itemEditor=link;addItem=true}}>Ubah</button><button class="icon-button danger-text" aria-label={`Hapus ${link.title}`} onclick={()=>removeItem(link)}>⌫</button></div></article>{/each}</div>{/if}</section>{/if}{#if editing&&item}<ChangeModal item={item} onClose={()=>editing=false} onSave={saveTree} {busy}/>{/if}{#if editingCover}<ChangeCoverModal onClose={()=>editingCover=false} onSave={saveCover} {busy}/>{/if}{#if addItem}<ItemModal item={itemEditor} onClose={()=>{addItem=false;itemEditor=null}} onSave={saveItem} {busy}/>{/if}
